INSERT INTO action_items (id, project_id, title, assignee, due_date, status, assigned_by, raw_message, created_at) VALUES ('ACT-SS-01', 'PRJ-SAPHANSUNG', 'สั่งสำรองปูนซ่อมโครงสร้าง BERCO Repair Mortar เพิ่มเติม', 'โฟร์แมนสะพานสูง / คุณไพโรจน์', '2026-09-05', 'OPEN', 'นายณัฐพงษ์ (พี่นัท)', 'เตรียมปูนซ่อมผิวคานฝ้าเพดานที่แตกร้าวและซ่อมบ่ารางน้ำล้นสระว่ายน้ำ', CURRENT_TIMESTAMP);
INSERT INTO action_items (id, project_id, title, assignee, due_date, status, assigned_by, raw_message, created_at) VALUES ('ACT-SS-02', 'PRJ-SAPHANSUNG', 'ตรวจรับมอบงานสกัดรื้อกระเบื้องและฉาบปรับผิวสระว่ายน้ำ 400 ตร.ม. ของช่างตี้', 'คุณไพโรจน์ / โฟร์แมนสะพานสูง', '2026-09-10', 'IN_PROGRESS', 'นายณัฐพงษ์ (พี่นัท)', 'ตรวจเช็คระดับความเรียบและรอยแตกร้าวทั่วทั้งพื้นและผนังสระก่อนส่งต่อทีมเชื่อม PVC Liner', CURRENT_TIMESTAMP);
INSERT INTO action_items (id, project_id, title, assignee, due_date, status, assigned_by, raw_message, created_at) VALUES ('ACT-SS-03', 'PRJ-SAPHANSUNG', 'ประสานงาน เจ.ซี. โซลูชั่น แอนด์ เซอร์วิส นัดหมายวันเข้าปูและเชื่อม PVC Liner 410 ตร.ม.', 'คุณจิราภรณ์ บึงลี (บุ๋ม) / คุณไพโรจน์', '2026-09-20', 'IN_PROGRESS', 'บจก.บลูเคอร์', 'เตรียมงานเชื่อม PVC Liner 410 ตร.ม. เชื่อมลู่ 6 เส้น และเติมน้ํารีดไลเนอร์ตามใบเสนอราคา 69-017', CURRENT_TIMESTAMP);
