INSERT INTO action_items (id, project_id, title, assignee, due_date, status, assigned_by, raw_message, created_at) VALUES ('ACT-SS-05', 'PRJ-SAPHANSUNG', 'ติดตาม บจก.อาร์คเทค ซัพพลาย เข้าติดตั้งโครงสร้างเหล็กและขึงผ้าใบแรงดึงสูง งวดที่ 2', 'อาร์คเทค ซัพพลาย / คุณไพโรจน์', '2026-10-15', 'IN_PROGRESS', 'บจก.บลูเคอร์', 'เตรียมความพร้อมฐานเสาและรอกยกเพื่อขึงผ้าใบแรงดึงสูงคลุมสระว่ายน้ำ', CURRENT_TIMESTAMP);
