INSERT INTO defects (id, project_id, code, title, description, zone, severity, status, assignee, photo_url, due_date, created_at) VALUES ('DEF-SS-01', 'PRJ-SAPHANSUNG', 'DEF-SS-01', 'ปูนฉาบเพดานเดิมบางส่วนร่อนตัวและแตกร้าว', 'ตรวจพบปูนฉาบใต้ท้องพื้นและแนวคานเดิมบางจุดร่อนตัว มีความเสี่ยงหลุดร่วง', 'โถงทางเดินชั้น 1 อาคารกิจกรรม', 'MEDIUM', 'IN_PROGRESS', 'ช่างตี้ / ทีมงานก่อสร้าง', 'assets/saphansung/สรุปของเข้าหน้างานสะพานสูง_Checklist_V4_preview.png', '2026-11-12', CURRENT_TIMESTAMP);
INSERT INTO defects (id, project_id, code, title, description, zone, severity, status, assignee, photo_url, due_date, created_at) VALUES ('DEF-SS-02', 'PRJ-SAPHANSUNG', 'DEF-SS-02', 'รอยแตกร้าวและบิ่นบริเวณขอบบ่ารางน้ำล้นเดิมรอบสระว่ายน้ำ', 'บ่ารางน้ำล้นเดิมมีรอยแตกกะเทาะ ทำให้ระดับน้ำล้นไม่สม่ำเสมอและไม่สามารถวางตะแกรง Grating ABS ได้แนบสนิท', 'รางน้ำล้นรอบสระว่ายน้ำ (ความยาว 75 เมตร)', 'HIGH', 'IN_PROGRESS', 'ช่างตี้ / โฟร์แมนสะพานสูง', 'assets/saphansung/สรุปของเข้าหน้างานสะพานสูง_Checklist_V4_preview.png', '2026-11-12', CURRENT_TIMESTAMP);
